const e="stjoseph-perth-bible-kalolsavam",u=2023,t="Read all 13 pages of the 2023 Program Sheet (house details, categories, 18 competitions, general rules). No fees, closing date, contact phone number or registration link address are printed (registration is by a House Registration Link not shown). The printed Day 3 venue is the Serbian Hall with no address. The Malayalam topic text for Elocution Sub Junior and Junior is printed in a broken font; the English topic names are written. The sheet says four centres but lists five houses (Orange Grove has a morning and an evening house). The Group Dance categories print as combined groups, so they are in the template as two combined groups. Single Song, Elocution and Bible Reading each have a Malayalam and an English section in the sheet; the template has one item each, so the sections are combined in one row.",i={Title:"Rules & Criteria",Subtitle:"Bible Kalolsavam, St. Joseph Syro-Malabar Parish Perth (SMC Catechism Department). Inter-house Bible arts competition for catechism students.",NoticeTitle:"Please Read Before Registering",Notice:"Competitions are only for catechism students of the year from the parish centres. Dates (2023 edition): {{Day1}}, {{Day2}} and {{Day3}}. All registrations are done through your House Registration Link.",Notes:["Programs, rules and regulations may change at the discretion of the Bible Kalolsavam Committee.","Please read each program for its own rules. You will be told the name of the Teacher-in-charge at your centre.","Houses and centres in the 2023 edition: {{HouseDetails}}."],Sections:[{Key:"general",Title:"General Rules",Items:["Please read each program thoroughly for its own further rules.","In Elocution and Solo competitions, participants must keep strictly to the time limit. A bell signals the end of the allowed time and the participant must leave the stage within 20 seconds after the bell.","Programs, rules, regulations and other elements of the Bible Kalolsavam may change at the discretion of the Bible Kalolsavam Committee."]},{Key:"eligibility",Title:"Who Can Enter",Items:["Competitions are only for catechism students of the year from the Orange Grove, Embleton, Willetton and Joondalup centres.","Sub Junior category: Year 1, 2 and 3. Junior category: Year 4, 5 and 6. Senior category: Year 7, 8 and 9. Super Senior category: Year 10, 11 and 12.","Each competing house belongs to a centre: Carmel (red, Orange Grove Morning), Olive (orange, Embleton), Sehion (white, Joondalup), Sinai (yellow, Orange Grove Evening) and Tabor (green, Willetton).","Sub Juniors can enter only one of Single Song Malayalam or Biblical Story Telling.","A student can enter Single Song in either Malayalam Devotional or English Devotional, not both.","A Junior can enter only one of Elocution Malayalam or Elocution English.","A participant can enter only one of Bible Reading English or Bible Reading Malayalam.","A participant can enter only one of Biblical Skit or Biblical Tableau.","Houses that cannot meet the minimum number of participants, or have fewer registrations, may be excused from the minimum with permission from the Catechism Director."]},{Key:"registration",Title:"How to Register",Items:["All registrations are done through the House Registration Link of your house.","The Teacher-in-charge of your centre will be named to you.","For group events, the Teacher-in-charge may hold a preliminary screening if more students come forward than are needed.","For Bible Reading, the Teacher-in-charge holds preliminary screening tests to find suitable participants from each house. Further details are given by the Teacher-in-charge after registration.","Each house may hold preliminary screening tests to choose the most suitable Bible Quiz candidates.","For Margamkali and Group Dance, the Teacher-in-charge may hold preliminary screening tests to find suitable participants if needed."]},{Key:"dates",Title:"Dates and Venue",Items:["Day 1: {{Day1}} in the Parish Hall. Day 2: {{Day2}} in the Parish Hall. Day 3: {{Day3}} in the Serbian Hall.","Parish Hall: {{Venue}}. Day 3: {{Day3Venue}}."]},{Key:"points",Title:"Points and Winners",Items:["Group items: first prize 9 points, second prize 6 points, third prize 3 points.","Individual items: first prize 5 points, second prize 3 points, third prize 1 point.","The house with the highest number of points gets the Group Winners trophy. The house with the second highest points gets the Runner-Up trophy."]},{Key:"prizes",Title:"Prizes and Awards",Items:["All winners receive individual prizes and certificates.","The judges choose a Best Actor and a Best Actress from the Biblical Skit.","The house with the most points receives the Group Winners trophy and the house with the second most points receives the Runner-Up trophy."]},{Key:"teams",Title:"Team Entries",Items:["Bible Quiz: one team from each house of 3 participants, one each from the Super Senior, Senior and Junior categories. If a team cannot find a Super Senior, it may add one more candidate from the Junior or Senior category.","Margamkali: teams of 6 to 12 participants, girls only, open to all categories.","Group Dance: each house may enter two teams, one in each category (Seniors and Super Seniors; Juniors and Sub Juniors). Teams of 8 to 12 participants.","Biblical Skit: one team from each house, open to all categories, up to 18 participants.","Biblical Tableau: one team from each house, open to all categories, 6 to 18 participants.","Group Song: one team from each house, open to all categories, 10 to 15 participants."]},{Key:"judging",Title:"Judging",Items:["The decision of the judging panel is final."]},{Key:"complaints",Title:"Contact With Judges",Items:["No one is allowed to contact the judges about the Bible Kalolsavam before, during or after the competition."]}],Documents:[{Title:"Bible Kalolsavam 2023 Program Sheet",Url:"https://www.syromalabarperth.org.au/assets/bulletins/1682294280-Bible-Kalolsavam-2023-Final.pdf"}]},n=[{ParticipantType:"Individual",Source:"Bible Kalolsavam 2023 Program Sheet p.13 (General Rules)",Sections:{About:null,TimeAndFormat:null,Rules:["Participants in Elocution and Solo competitions must strictly keep the time limit. A bell signals the end and the participant must leave the stage within 20 seconds."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Rules
- Participants in Elocution and Solo competitions must strictly keep the time limit. A bell signals the end and the participant must leave the stage within 20 seconds.`}],o=[{AgeGroup:"Sub Junior",Source:"Bible Kalolsavam 2023 Program Sheet p.1-9",Sections:{About:null,TimeAndFormat:null,Rules:["Sub Juniors can enter only one of Single Song Malayalam or Biblical Story Telling.","Sub Juniors do not take part in Single Song English, Elocution English, Bible Reading, Essay Writing, Poem Writing or Bible Verses Writing."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Rules
- Sub Juniors can enter only one of Single Song Malayalam or Biblical Story Telling.
- Sub Juniors do not take part in Single Song English, Elocution English, Bible Reading, Essay Writing, Poem Writing or Bible Verses Writing.`}],a=JSON.parse(`[{"Title":"Single Song","Source":"Bible Kalolsavam 2023 Program Sheet p.2 (Single Song, Malayalam and English Devotional)","Sections":{"About":["Malayalam Devotional: open to all four categories, boys and girls separately. English Devotional: limited to Juniors, Seniors and Super Seniors."],"TimeAndFormat":["3 minutes per participant."],"Rules":["A student can enter either Malayalam Devotional or English Devotional.","Sub Juniors can enter only one of Single Song Malayalam or Biblical Story Telling."],"Allowed":["Only Malayalam Christian devotionals in the Malayalam section. Only English Christian devotionals in the English section."],"NotAllowed":["Karaoke."],"Judging":null,"Points":null,"Notes":null},"Markdown":"## About this competition\\n- Malayalam Devotional: open to all four categories, boys and girls separately. English Devotional: limited to Juniors, Seniors and Super Seniors.\\n\\n## Time and format\\n- 3 minutes per participant.\\n\\n## Rules\\n- A student can enter either Malayalam Devotional or English Devotional.\\n- Sub Juniors can enter only one of Single Song Malayalam or Biblical Story Telling.\\n\\n## Allowed\\n- Only Malayalam Christian devotionals in the Malayalam section. Only English Christian devotionals in the English section.\\n\\n## Not allowed\\n- Karaoke."},{"Title":"Elocution","Source":"Bible Kalolsavam 2023 Program Sheet p.3 (Elocution, Malayalam and English)","Sections":{"About":["Malayalam: limited to Sub Juniors and Juniors, on a biblical topic. English: limited to Juniors, Seniors and Super Seniors, on a Biblical or spiritual topic."],"TimeAndFormat":["3 minutes per participant."],"Rules":["Juniors can enter only one of Elocution Malayalam or Elocution English.","2023 topics: Sub Junior Malayalam, My Favourite Saint. Junior Malayalam, My Church. Junior English, The Parable of the Prodigal Son.","Senior and Super Senior English: report to the Registration Counter 45 minutes before the competition starts. The topic is given 30 minutes before the competition."],"Allowed":null,"NotAllowed":["Holding any properties or reading materials."],"Judging":null,"Points":null,"Notes":null},"Markdown":"## About this competition\\n- Malayalam: limited to Sub Juniors and Juniors, on a biblical topic. English: limited to Juniors, Seniors and Super Seniors, on a Biblical or spiritual topic.\\n\\n## Time and format\\n- 3 minutes per participant.\\n\\n## Rules\\n- Juniors can enter only one of Elocution Malayalam or Elocution English.\\n- 2023 topics: Sub Junior Malayalam, My Favourite Saint. Junior Malayalam, My Church. Junior English, The Parable of the Prodigal Son.\\n- Senior and Super Senior English: report to the Registration Counter 45 minutes before the competition starts. The topic is given 30 minutes before the competition.\\n\\n## Not allowed\\n- Holding any properties or reading materials."},{"Title":"Bible Reading","Source":"Bible Kalolsavam 2023 Program Sheet p.4 (Bible Reading, English and Malayalam)","Sections":{"About":["English and Malayalam sections. Limited to Juniors, Seniors and Super Seniors, with at most 3 participants per category.","Passages are given from any of the 4 Gospels."],"TimeAndFormat":["2 minutes per participant."],"Rules":["A participant can enter only one of Bible Reading English or Bible Reading Malayalam.","The Teacher-in-charge holds preliminary screening tests to find suitable participants from each house. Further details are given after registration."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## About this competition\\n- English and Malayalam sections. Limited to Juniors, Seniors and Super Seniors, with at most 3 participants per category.\\n- Passages are given from any of the 4 Gospels.\\n\\n## Time and format\\n- 2 minutes per participant.\\n\\n## Rules\\n- A participant can enter only one of Bible Reading English or Bible Reading Malayalam.\\n- The Teacher-in-charge holds preliminary screening tests to find suitable participants from each house. Further details are given after registration."},{"Title":"Essay Writing","Source":"Bible Kalolsavam 2023 Program Sheet p.5 (Essay Writing, English)","Sections":{"About":["English. Limited to Juniors, Seniors and Super Seniors. Based on a Biblical or spiritual topic announced when the competition starts."],"TimeAndFormat":["40 minutes."],"Rules":["Report to the Registration Counter 45 minutes before the competition starts.","Bring your own stationery (pencil, eraser and so on).","Write on the official competition paper, which the Department gives at the start. Write legibly."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## About this competition\\n- English. Limited to Juniors, Seniors and Super Seniors. Based on a Biblical or spiritual topic announced when the competition starts.\\n\\n## Time and format\\n- 40 minutes.\\n\\n## Rules\\n- Report to the Registration Counter 45 minutes before the competition starts.\\n- Bring your own stationery (pencil, eraser and so on).\\n- Write on the official competition paper, which the Department gives at the start. Write legibly."},{"Title":"Poem Writing","Source":"Bible Kalolsavam 2023 Program Sheet p.5 (Poem Writing, English)","Sections":{"About":["English. Limited to Juniors, Seniors and Super Seniors. Based on a Biblical or spiritual topic announced when the competition starts."],"TimeAndFormat":["40 minutes."],"Rules":["Report to the Registration Counter 45 minutes before the competition starts.","Bring your own stationery (pencil, eraser and so on).","Write on the official competition paper, which the Department gives at the start. Write legibly."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## About this competition\\n- English. Limited to Juniors, Seniors and Super Seniors. Based on a Biblical or spiritual topic announced when the competition starts.\\n\\n## Time and format\\n- 40 minutes.\\n\\n## Rules\\n- Report to the Registration Counter 45 minutes before the competition starts.\\n- Bring your own stationery (pencil, eraser and so on).\\n- Write on the official competition paper, which the Department gives at the start. Write legibly."},{"Title":"Pencil Drawing","Source":"Bible Kalolsavam 2023 Program Sheet p.6 (Pencil Drawing)","Sections":{"About":["Open to all four categories. Based on a Biblical or spiritual theme announced when the competition starts.","Sub Junior theme is chosen from six topics: The parable of the sower; Jesus and Zacchaeus; The Prodigal son and Father; Baptism of Jesus; Jesus entering Jerusalem on the donkey; Jesus standing before Pilate. The other categories get their topic when the competition starts."],"TimeAndFormat":["45 minutes."],"Rules":["Report to the Registration Counter 45 minutes before the competition starts.","Bring your own stationery (pencil, eraser and so on).","Use the official competition paper, which the Department gives at the start."],"Allowed":null,"NotAllowed":["Colouring materials."],"Judging":null,"Points":null,"Notes":null},"Markdown":"## About this competition\\n- Open to all four categories. Based on a Biblical or spiritual theme announced when the competition starts.\\n- Sub Junior theme is chosen from six topics: The parable of the sower; Jesus and Zacchaeus; The Prodigal son and Father; Baptism of Jesus; Jesus entering Jerusalem on the donkey; Jesus standing before Pilate. The other categories get their topic when the competition starts.\\n\\n## Time and format\\n- 45 minutes.\\n\\n## Rules\\n- Report to the Registration Counter 45 minutes before the competition starts.\\n- Bring your own stationery (pencil, eraser and so on).\\n- Use the official competition paper, which the Department gives at the start.\\n\\n## Not allowed\\n- Colouring materials."},{"Title":"Biblical Story Telling","Source":"Bible Kalolsavam 2023 Program Sheet p.7 (Biblical Story Telling, English)","Sections":{"About":["English. Limited to the Sub Junior category. The participant tells a story from the Parables of the New Testament."],"TimeAndFormat":["4 minutes."],"Rules":["Sub Juniors can enter only one of Single Song Malayalam or Biblical Story Telling."],"Allowed":["Dressing up. One property (stick, animal and so on)."],"NotAllowed":["Reading materials.","Stage preparation. Parents or helpers cannot go on stage to prepare.","Background music or any other audio. The participant must be vocal only."],"Judging":null,"Points":null,"Notes":null},"Markdown":"## About this competition\\n- English. Limited to the Sub Junior category. The participant tells a story from the Parables of the New Testament.\\n\\n## Time and format\\n- 4 minutes.\\n\\n## Rules\\n- Sub Juniors can enter only one of Single Song Malayalam or Biblical Story Telling.\\n\\n## Allowed\\n- Dressing up. One property (stick, animal and so on).\\n\\n## Not allowed\\n- Reading materials.\\n- Stage preparation. Parents or helpers cannot go on stage to prepare.\\n- Background music or any other audio. The participant must be vocal only."},{"Title":"Bible Verses Writing","Source":"Bible Kalolsavam 2023 Program Sheet p.7-8 (Bible Verses Writing, English)","Sections":{"About":["English. Limited to Junior, Senior and Super Senior. Write as many Bible verses as possible in the time given."],"TimeAndFormat":["30 minutes."],"Rules":["Report to the Registration Counter 10 minutes before the competition starts.","Quote each verse with the name of the Book, the chapter and the verse number. Verses are from the NRSV Catholic Edition Bible.","Write no more than one verse from a chapter. Example: after Isaiah 45:2, another verse from Isaiah chapter 45 is not allowed.","Bring your own stationery (pencil, eraser and so on).","Write on the official competition paper, which the Department gives at the start. Write legibly."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## About this competition\\n- English. Limited to Junior, Senior and Super Senior. Write as many Bible verses as possible in the time given.\\n\\n## Time and format\\n- 30 minutes.\\n\\n## Rules\\n- Report to the Registration Counter 10 minutes before the competition starts.\\n- Quote each verse with the name of the Book, the chapter and the verse number. Verses are from the NRSV Catholic Edition Bible.\\n- Write no more than one verse from a chapter. Example: after Isaiah 45:2, another verse from Isaiah chapter 45 is not allowed.\\n- Bring your own stationery (pencil, eraser and so on).\\n- Write on the official competition paper, which the Department gives at the start. Write legibly."},{"Title":"Bible Quiz","Source":"Bible Kalolsavam 2023 Program Sheet p.8 (Bible Quiz, English)","Sections":{"About":["A stage competition of direct questions from the Quiz Master. Each team gets points for its answers.","One team from each house of 3 participants, one each from the Super Senior, Senior and Junior categories. If a team has no Super Senior, it may add one more candidate from the Junior or Senior category.","2023 topics: {{BibleQuizTopic}}."],"TimeAndFormat":null,"Rules":["The Bible Quiz Master decides the quiz program and may discuss any issue with the Catechism Director.","Each house may hold preliminary screening tests to choose the best candidates.","Study the NRSV Catholic Edition Bible."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## About this competition\\n- A stage competition of direct questions from the Quiz Master. Each team gets points for its answers.\\n- One team from each house of 3 participants, one each from the Super Senior, Senior and Junior categories. If a team has no Super Senior, it may add one more candidate from the Junior or Senior category.\\n- 2023 topics: {{BibleQuizTopic}}.\\n\\n## Rules\\n- The Bible Quiz Master decides the quiz program and may discuss any issue with the Catechism Director.\\n- Each house may hold preliminary screening tests to choose the best candidates.\\n- Study the NRSV Catholic Edition Bible."},{"Title":"Fancy Dress","Source":"Bible Kalolsavam 2023 Program Sheet p.9 (Fancy Dress)","Sections":{"About":["Limited to Sub Junior. The participant dresses as one character: a Biblical figure, a Saint or a Religious Head."],"TimeAndFormat":["1 minute per participant."],"Rules":null,"Allowed":["Singing or speaking in English or Malayalam."],"NotAllowed":["Background music, audio support or sound effects.","Stage preparation. Parents or helpers cannot go on stage to prepare."],"Judging":null,"Points":null,"Notes":null},"Markdown":"## About this competition\\n- Limited to Sub Junior. The participant dresses as one character: a Biblical figure, a Saint or a Religious Head.\\n\\n## Time and format\\n- 1 minute per participant.\\n\\n## Allowed\\n- Singing or speaking in English or Malayalam.\\n\\n## Not allowed\\n- Background music, audio support or sound effects.\\n- Stage preparation. Parents or helpers cannot go on stage to prepare."},{"Title":"Margamkali","Source":"Bible Kalolsavam 2023 Program Sheet p.9 (Margamkali, Girls Only)","Sections":{"About":["Girls only. Open to all categories. Teams of 6 to 12 participants."],"TimeAndFormat":["5 minutes per team."],"Rules":["Perform to traditional Margamkali songs.","The Teacher-in-charge may hold preliminary screening tests to find suitable participants if needed."],"Allowed":["Karaoke or singing."],"NotAllowed":["Cinematic songs."],"Judging":null,"Points":null,"Notes":null},"Markdown":"## About this competition\\n- Girls only. Open to all categories. Teams of 6 to 12 participants.\\n\\n## Time and format\\n- 5 minutes per team.\\n\\n## Rules\\n- Perform to traditional Margamkali songs.\\n- The Teacher-in-charge may hold preliminary screening tests to find suitable participants if needed.\\n\\n## Allowed\\n- Karaoke or singing.\\n\\n## Not allowed\\n- Cinematic songs."},{"Title":"Group Dance","Source":"Bible Kalolsavam 2023 Program Sheet p.10 (Group Dance)","Sections":{"About":["Two categories: Seniors and Super Seniors; Juniors and Sub Juniors. Each house may enter two teams. Teams of 8 to 12 participants.","Give special focus to Biblical themes, a Saint's story or spiritual life."],"TimeAndFormat":["5 minutes per team."],"Rules":["Use only Biblical or Devotional songs.","The Teacher-in-charge may hold preliminary screening tests to find suitable participants if needed.","The dance must start and finish as a dance."],"Allowed":["Fusion. Boys and girls together."],"NotAllowed":["Storytelling in any part of the dance."],"Judging":null,"Points":null,"Notes":null},"Markdown":"## About this competition\\n- Two categories: Seniors and Super Seniors; Juniors and Sub Juniors. Each house may enter two teams. Teams of 8 to 12 participants.\\n- Give special focus to Biblical themes, a Saint's story or spiritual life.\\n\\n## Time and format\\n- 5 minutes per team.\\n\\n## Rules\\n- Use only Biblical or Devotional songs.\\n- The Teacher-in-charge may hold preliminary screening tests to find suitable participants if needed.\\n- The dance must start and finish as a dance.\\n\\n## Allowed\\n- Fusion. Boys and girls together.\\n\\n## Not allowed\\n- Storytelling in any part of the dance."},{"Title":"Biblical Skit","Source":"Bible Kalolsavam 2023 Program Sheet p.11 (Biblical Skit, Malayalam)","Sections":{"About":["Malayalam. One team from each house, open to all categories, up to 18 participants.","The skit must be purely Bible based, with all characters from the Bible or Bible related.","The judges choose a Best Actor and a Best Actress."],"TimeAndFormat":["15 minutes of stage time and 10 minutes of stage preparation."],"Rules":["Participants can enter only one of Biblical Skit or Biblical Tableau.","Recorded voice or audio is allowed, but the file must not be longer than 15 minutes.","Email the audio file to the Catechism Principal ({{CatechismPrincipal}}) before {{SkitAudioDeadline}}. The Catechism Principal screens it first and tells you if changes are needed."],"Allowed":null,"NotAllowed":["Stage preparation before the set time."],"Judging":null,"Points":null,"Notes":null},"Markdown":"## About this competition\\n- Malayalam. One team from each house, open to all categories, up to 18 participants.\\n- The skit must be purely Bible based, with all characters from the Bible or Bible related.\\n- The judges choose a Best Actor and a Best Actress.\\n\\n## Time and format\\n- 15 minutes of stage time and 10 minutes of stage preparation.\\n\\n## Rules\\n- Participants can enter only one of Biblical Skit or Biblical Tableau.\\n- Recorded voice or audio is allowed, but the file must not be longer than 15 minutes.\\n- Email the audio file to the Catechism Principal ({{CatechismPrincipal}}) before {{SkitAudioDeadline}}. The Catechism Principal screens it first and tells you if changes are needed.\\n\\n## Not allowed\\n- Stage preparation before the set time."},{"Title":"Biblical Tableau","Source":"Bible Kalolsavam 2023 Program Sheet p.11 (Biblical Tableau)","Sections":{"About":["One team from each house, open to all categories, 6 to 18 participants.","A Biblical theme, incident or parable is shown by motionless characters."],"TimeAndFormat":["1 minute of stage time and 5 minutes of stage preparation."],"Rules":["Participants can enter only one of Biblical Skit or Biblical Tableau.","Background music, audio support or sound effects are allowed to carry the message, in English or Malayalam, but must be shorter than one minute. Anything longer is not considered."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## About this competition\\n- One team from each house, open to all categories, 6 to 18 participants.\\n- A Biblical theme, incident or parable is shown by motionless characters.\\n\\n## Time and format\\n- 1 minute of stage time and 5 minutes of stage preparation.\\n\\n## Rules\\n- Participants can enter only one of Biblical Skit or Biblical Tableau.\\n- Background music, audio support or sound effects are allowed to carry the message, in English or Malayalam, but must be shorter than one minute. Anything longer is not considered."},{"Title":"Group Song","Source":"Bible Kalolsavam 2023 Program Sheet p.12 (Group Song)","Sections":{"About":["One team from each house, open to all categories, 10 to 15 participants.","Theme: {{GroupSongTheme}}."],"TimeAndFormat":["6 minutes."],"Rules":["Sing purely Malayalam Devotional songs."],"Allowed":null,"NotAllowed":["Karaoke and instruments."],"Judging":null,"Points":null,"Notes":null},"Markdown":"## About this competition\\n- One team from each house, open to all categories, 10 to 15 participants.\\n- Theme: {{GroupSongTheme}}.\\n\\n## Time and format\\n- 6 minutes.\\n\\n## Rules\\n- Sing purely Malayalam Devotional songs.\\n\\n## Not allowed\\n- Karaoke and instruments."}]`),r=[{Title:"Group Dance",AgeGroup:"GDance Jr+SubJr",Source:"Bible Kalolsavam 2023 Program Sheet p.10",Sections:{About:["Juniors and Sub Juniors category. Each house may enter two teams across the two Group Dance categories."],TimeAndFormat:null,Rules:null,Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## About this competition
- Juniors and Sub Juniors category. Each house may enter two teams across the two Group Dance categories.`},{Title:"Group Dance",AgeGroup:"GDance Sr+SupSr",Source:"Bible Kalolsavam 2023 Program Sheet p.10",Sections:{About:["Seniors and Super Seniors category."],TimeAndFormat:null,Rules:null,Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## About this competition
- Seniors and Super Seniors category.`},{Title:"Bible Quiz",AgeGroup:"BQuiz Jr-SupSr",Source:"Bible Kalolsavam 2023 Program Sheet p.8",Sections:{About:["Team of 3: one Super Senior, one Senior and one Junior."],TimeAndFormat:null,Rules:null,Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## About this competition
- Team of 3: one Super Senior, one Senior and one Junior.`}],l=[{Key:"Day1",Kind:"date",Label:"Day 1",Value:"2023-04-29",Source:"Bible Kalolsavam 2023 Program Sheet p.1"},{Key:"Day2",Kind:"date",Label:"Day 2",Value:"2023-05-13",Source:"Bible Kalolsavam 2023 Program Sheet p.1"},{Key:"Day3",Kind:"date",Label:"Day 3",Value:"2023-06-03",Source:"Bible Kalolsavam 2023 Program Sheet p.1"},{Key:"Venue",Kind:"address",Label:"Venue for Day 1 and Day 2 (Parish Hall)",Value:{Name:"St. Joseph Syro-Malabar Parish Perth, Parish Hall",Address:"347 Kelvin Road",City:"Orange Grove, Western Australia 6109",MapUrl:"",Directions:""},Source:"Bible Kalolsavam 2023 Program Sheet p.1"},{Key:"Day3Venue",Kind:"address",Label:"Venue for Day 3",Value:{Name:"Serbian Hall",Address:"",City:"",MapUrl:"",Directions:"The program sheet prints only the hall name for Day 3."},Source:"Bible Kalolsavam 2023 Program Sheet p.1"},{Key:"SkitAudioDeadline",Kind:"date",Label:"Last date to email the Biblical Skit audio file",Value:"2023-05-10",Source:"Bible Kalolsavam 2023 Program Sheet p.11 (Biblical Skit)"},{Key:"CatechismPrincipal",Kind:"contact",Label:"Catechism Principal (Biblical Skit audio file)",Value:{Name:"Catechism Principal",Role:"Screens the Biblical Skit audio file",Phone:"",WhatsApp:"",Email:"principal.smcatechism@gmail.com"},Source:"Bible Kalolsavam 2023 Program Sheet p.11 (Biblical Skit)"},{Key:"ReportingTime",Kind:"text",Label:"Reporting time for written and drawing items",Value:"45 minutes before the competition starts (10 minutes for Bible Verses Writing)",Source:"Bible Kalolsavam 2023 Program Sheet p.4-8"},{Key:"BibleQuizTopic",Kind:"text",Label:"Bible Quiz topic (2023)",Value:"Gospel of St. John; Letter to Galatians; Letter to Philippians; Letter to Ephesians; Letter to Colossians",Source:"Bible Kalolsavam 2023 Program Sheet p.8"},{Key:"GroupSongTheme",Kind:"text",Label:"Group Song theme (2023)",Value:"Eucharistic Songs (Divyakaarunya Geethangal)",Source:"Bible Kalolsavam 2023 Program Sheet p.12"},{Key:"HouseDetails",Kind:"text",Label:"Houses, colours and centres (2023)",Value:"Carmel (red, Orange Grove Morning); Olive (orange, Embleton); Sehion (white, Joondalup); Sinai (yellow, Orange Grove Evening); Tabor (green, Willetton)",Source:"Bible Kalolsavam 2023 Program Sheet p.1"}],s=[{Claim:"All rules, categories, times, team sizes, points and dates are from the parish's own Bible Kalolsavam 2023 Program Sheet.",SourceType:"Primary - organiser's own program sheet",Source:"Bible Kalolsavam 2023 Program Sheet",Url:"https://www.syromalabarperth.org.au/assets/bulletins/1682294280-Bible-Kalolsavam-2023-Final.pdf"}],c={TemplateKey:e,Year:2023,Note:t,Page:i,ParticipantTypes:n,AgeGroups:o,Competitions:a,CompetitionAgeGroups:r,Variables:l,Evidence:s};export{o as AgeGroups,r as CompetitionAgeGroups,a as Competitions,s as Evidence,t as Note,i as Page,n as ParticipantTypes,e as TemplateKey,l as Variables,u as Year,c as default};
